import AppKit
import ImageIO
import UniformTypeIdentifiers
import ClipboardCore

enum ClipboardCapture {
    static let maximumBytes = 20 * 1024 * 1024
    static let ignoredTypes: Set<String> = [
        "org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType", "com.agilebits.onepassword"
    ]
    static let supportedTypes: Set<String> = [
        NSPasteboard.PasteboardType.string.rawValue, NSPasteboard.PasteboardType.rtf.rawValue,
        NSPasteboard.PasteboardType.rtfd.rawValue, NSPasteboard.PasteboardType.html.rawValue,
        NSPasteboard.PasteboardType.png.rawValue, NSPasteboard.PasteboardType.tiff.rawValue,
        NSPasteboard.PasteboardType.URL.rawValue, NSPasteboard.PasteboardType.fileURL.rawValue,
        "public.jpeg", "public.utf16-plain-text", "public.utf8-tab-separated-values"
    ]

    enum Outcome { case captured(ClipDraft), ignored, tooLarge }

    static func read(_ pasteboard: NSPasteboard, source: NSRunningApplication?) -> Outcome {
        guard let items = pasteboard.pasteboardItems, !items.isEmpty else { return .ignored }
        if items.contains(where: { !$0.types.map(\.rawValue).filter(ignoredTypes.contains).isEmpty }) { return .ignored }
        var total = 0
        var representations: [[ClipRepresentation]] = []
        for item in items {
            var values: [ClipRepresentation] = []
            for type in item.types where supportedTypes.contains(type.rawValue) {
                guard let data = item.data(forType: type), !data.isEmpty else { continue }
                total += data.count
                guard total <= maximumBytes else { return .tooLarge }
                values.append(ClipRepresentation(type: type.rawValue, data: data))
            }
            if !values.isEmpty { representations.append(values) }
        }
        guard !representations.isEmpty else { return .ignored }
        let all = representations.flatMap { $0 }
        var text = pasteboard.string(forType: .string) ?? pasteboard.string(forType: .URL) ?? ""
        if text.isEmpty, let rtf = all.first(where: { $0.type == NSPasteboard.PasteboardType.rtf.rawValue }),
           let attributed = try? NSAttributedString(data: rtf.data, options: [.documentType: NSAttributedString.DocumentType.rtf], documentAttributes: nil) {
            text = attributed.string
        }
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        var kind: ClipKind = .text
        var title = String(trimmed.split(whereSeparator: \.isNewline).first.map(String.init)?.prefix(160) ?? "富文本".prefix(160))
        var thumbnail: Data?
        let fileURLs = items.compactMap { $0.string(forType: .fileURL) }.compactMap(URL.init(string:))
        if !fileURLs.isEmpty {
            kind = .file
            title = fileURLs.count == 1 ? fileURLs[0].lastPathComponent : "\(fileURLs.count) 个文件"
            text = fileURLs.map(\.path).joined(separator: "\n")
        } else if let picture = all.first(where: { [NSPasteboard.PasteboardType.png.rawValue, "public.jpeg", NSPasteboard.PasteboardType.tiff.rawValue].contains($0.type) }) {
            kind = .image
            title = "图片"
            if let source = CGImageSourceCreateWithData(picture.data as CFData, nil) {
                if let properties = CGImageSourceCopyPropertiesAtIndex(source, 0, nil) as? [CFString: Any],
                   let width = properties[kCGImagePropertyPixelWidth] as? Int, let height = properties[kCGImagePropertyPixelHeight] as? Int {
                    title = "\(width) × \(height)"
                }
                let options: [CFString: Any] = [kCGImageSourceCreateThumbnailFromImageAlways: true,
                    kCGImageSourceThumbnailMaxPixelSize: 560, kCGImageSourceCreateThumbnailWithTransform: true]
                if let image = CGImageSourceCreateThumbnailAtIndex(source, 0, options as CFDictionary) {
                    thumbnail = NSBitmapImageRep(cgImage: image).representation(using: .png, properties: [:])
                }
            }
        } else if let url = URL(string: trimmed), ["http", "https", "mailto"].contains(url.scheme?.lowercased() ?? ""), !trimmed.contains(where: \.isWhitespace) {
            kind = .link; title = url.host ?? trimmed
        }
        return .captured(ClipDraft(kind: kind, title: title.isEmpty ? "空白文本" : title,
            text: String(text.prefix(1_000_000)), sourceName: source?.localizedName ?? "未知应用",
            sourceBundle: source?.bundleIdentifier ?? "", thumbnail: thumbnail, payload: ClipPayload(items: representations)))
    }
}
